def tarjan_subset(nodes, node_set, adj):
    """SCC of induced subgraph on members (all in node_set); returns list of lists."""
    idx = {}
    low = {}
    onst = set()
    stack = []
    comps = []
    for root in nodes:
        if root in idx:
            continue
        work = [[root, 0]]
        while work:
            fr = work[-1]
            v = fr[0]
            if fr[1] == 0:
                idx[v] = len(idx)
                low[v] = idx[v]
                stack.append(v)
                onst.add(v)
            recurse = False
            av = adj[v]
            ln = len(av)
            pi = fr[1]
            while pi < ln:
                w = av[pi]
                pi += 1
                if w in node_set:
                    if w not in idx:
                        fr[1] = pi
                        work.append([w, 0])
                        recurse = True
                        break
                    elif w in onst and idx[w] < low[v]:
                        low[v] = idx[w]
            if recurse:
                continue
            work.pop()
            if low[v] == idx[v]:
                comp = []
                while True:
                    w = stack.pop()
                    onst.discard(w)
                    comp.append(w)
                    if w == v:
                        break
                comps.append(comp)
            if work:
                u = work[-1][0]
                if low[v] < low[u]:
                    low[u] = low[v]
    return comps


def hierholzer(nodes_idx, adj_eid, adj_tgt, deg, edge_lookup, m_nodes_cnt):
    """adj_eid[u] list of edge ids; adj_tgt[u] parallel target ids."""
    tot = len(nodes_idx)
    ptr = [0] * tot
    stack = [nodes_idx[0]]
    popnodes = []
    while stack:
        u = stack[-1]
        if ptr[u] < deg[u]:
            stack.append(adj_tgt[u][ptr[u]])
            ptr[u] += 1
        else:
            popnodes.append(stack.pop())
    popnodes.reverse()
    out = []
    for i in range(len(popnodes) - 1):
        u = popnodes[i]
        v = popnodes[i + 1]
        out.append(edge_lookup[u][v].pop(0))
    return out


